      INSERT INTO born (word, run, source) SELECT (CASE WHEN length(NEW.line) > length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.line, 1, length(NEW.line) - length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.line, 1, 1) END), NULL, 0 WHERE NOT EXISTS (SELECT 1 FROM label WHERE word = (CASE WHEN length(NEW.line) > length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.line, 1, length(NEW.line) - length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.line, 1, 1) END));
      INSERT INTO run (input, line, direction, kind, word) VALUES (NEW.id, substr(NEW.line, length((CASE WHEN length(NEW.line) > length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.line, 1, length(NEW.line) - length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.line, 1, 1) END)) + 4), 'start', 'teach', (CASE WHEN length(NEW.line) > length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.line, 1, length(NEW.line) - length(ltrim(NEW.line, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.line, 1, 1) END));
    END

