CREATE TRIGGER born_go AFTER INSERT ON born BEGIN
      INSERT INTO fire (run, trig, subject) VALUES (NEW.run, 9, NEW.id);
      INSERT INTO fire (run, trig, subject) SELECT NEW.run, (SELECT gate FROM label WHERE word = 'source'), (SELECT gate FROM label WHERE word = NEW.word) WHERE NEW.source = 1 AND EXISTS (SELECT 1 FROM label WHERE word = NEW.word);
    END

CREATE TRIGGER hop_go AFTER INSERT ON hop BEGIN
      INSERT INTO receipt (run, gate, shard) VALUES (NEW.run, NEW.gate, NEW.shard);
      INSERT INTO build (run, rid) SELECT NEW.run, (SELECT max(id) FROM receipt WHERE run = NEW.run) WHERE NEW.gate = 15 AND (SELECT kind FROM run WHERE id = NEW.run) <> 'teach'
        AND (SELECT count(*) FROM receipt WHERE run = NEW.run AND gate = 15) % 2 = 0;
      INSERT INTO fire (run, gate, shard, trig, rest) SELECT NEW.run, NEW.gate, NEW.shard, NEW.trig, coalesce((SELECT word FROM label WHERE gate = NEW.remainder), '') || coalesce(NEW.rest, '') WHERE NEW.trig IS NOT NULL;
      INSERT INTO "end" (run) SELECT NEW.run WHERE NEW.remainder IS NULL;
      INSERT INTO born (word, run, source) SELECT (CASE WHEN length(NEW.rest) > length(ltrim(NEW.rest, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.rest, 1, length(NEW.rest) - length(ltrim(NEW.rest, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.rest, 1, 1) END), NEW.run, (SELECT kind FROM run WHERE id = NEW.run) = 'line'
        WHERE NEW.remainder IS NOT NULL AND NEW.rest <> '' AND NOT EXISTS (SELECT 1 FROM label WHERE word = (CASE WHEN length(NEW.rest) > length(ltrim(NEW.rest, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')) THEN substr(NEW.rest, 1, length(NEW.rest) - length(ltrim(NEW.rest, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))) ELSE substr(NEW.rest, 1, 1) END));
      DELETE FROM hop WHERE id = NEW.id;
