CREATE TRIGGER build_go AFTER INSERT ON build BEGIN
      INSERT INTO sheet (run, name, value) VALUES (NEW.run, 'BUILD', mother((SELECT trim(group_concat(p, '')) FROM (SELECT id, CASE WHEN w = 'var' AND n1 = ' ' THEN '' WHEN w = ' ' AND w1 = 'var' THEN '' WHEN w1 = ' ' AND w2 = 'var' THEN coalesce(coalesce((SELECT value FROM sheet WHERE run = NEW.run AND name = w ORDER BY id DESC LIMIT 1), (SELECT value FROM sheet WHERE run = (SELECT parent FROM run WHERE id = NEW.run) AND name = w ORDER BY id DESC LIMIT 1), (SELECT value FROM sheet WHERE run = (SELECT root FROM run WHERE id = NEW.run) AND name = w ORDER BY id DESC LIMIT 1)), '') ELSE w END AS p FROM (SELECT x.id AS id, l.word AS w, lag(l.word, 1) OVER o AS w1, lag(l.word, 2) OVER o AS w2, lead(l.word, 1) OVER o AS n1 FROM receipt x JOIN label l ON l.gate = x.gate WHERE x.run = NEW.run AND x.id > coalesce((SELECT max(id) FROM receipt WHERE run = NEW.run AND gate = 15 AND id < NEW.rid), 0) AND x.id < NEW.rid WINDOW o AS (ORDER BY x.id)) ORDER BY id)), NEW.run));
    END

CREATE TRIGGER end_teach AFTER INSERT ON "end" WHEN (SELECT kind FROM run WHERE id = NEW.run) = 'teach' BEGIN
      UPDATE formula SET ended = 1 WHERE gate = (SELECT gate FROM label WHERE word = (SELECT word FROM run WHERE id = NEW.run)) AND ended = 0;
      INSERT INTO formula (gate, run) VALUES ((SELECT gate FROM label WHERE word = (SELECT word FROM run WHERE id = NEW.run)), NEW.run);
    END

CREATE TRIGGER end_return AFTER INSERT ON "end" WHEN (SELECT kind FROM run WHERE id = NEW.run) = 'defrow' BEGIN
      INSERT INTO sheet (run, name, value) SELECT parent, word, NEW.run FROM run WHERE id = NEW.run;
    END
